export function Dialog({
  title,
  children,
  onClose,
  className = '',
  closeKey,
  onShortcutClose,
  active = true,
  scrimClassName = '',
}: {
  title: string;
  children: React.ReactNode;
  onClose?: () => void;
  className?: string;
  closeKey?: string;
  onShortcutClose?: () => void;
  active?: boolean;
  scrimClassName?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  // Swapping dialogs must transfer keyboard focus in the same DOM commit.
  // A passive effect leaves a gap where the next key is delivered to BODY.
  useLayoutEffect(() => {
    if (!active) return;
    const previous = document.activeElement as HTMLElement | null;
    ref.current?.focus();
    return () => previous?.focus({ preventScroll: true });
  }, [active]);
  return (
    <div
      className={`modal-scrim ${scrimClassName}`}
      aria-hidden={!active || undefined}
      inert={!active}
    >
      <div
        ref={ref}
        tabIndex={-1}
        role={active ? 'dialog' : undefined}
        aria-modal={active || undefined}
        aria-label={title}
        className={`dialog ${className}`}
        onKeyDown={(e) => {
          const code = canonicalHotkey(e.code);
          if ((e.key === 'Escape' || code === closeKey) && onClose) {
            e.preventDefault();
            e.stopPropagation();
            if (code === closeKey && onShortcutClose) onShortcutClose();
            else onClose();
          }
          if (e.key === 'Tab') {
            const nodes = Array.from(
              ref.current?.querySelectorAll<HTMLElement>(
                'button:not(:disabled),input:not(:disabled),select,textarea,[tabindex="0"]',
              ) ?? [],
            ).filter(
              (node) =>
                node.getClientRects().length && !node.closest('[inert],[aria-hidden="true"]'),
            );
            if (!nodes?.length) return;
            const first = nodes[0],
              last = nodes[nodes.length - 1];
            if (e.shiftKey && document.activeElement === first) {
              e.preventDefault();
              last.focus();
            } else if (!e.shiftKey && document.activeElement === last) {
              e.preventDefault();
              first.focus();
            }
          }
        }}
      >
        <div className="dialog-heading">
          <h2>{title}</h2>
          {onClose && !className.split(' ').includes('stage-dialog') ? (
            <button className="icon-button" aria-label="Close" onClick={onClose}>
              <Icon name="close" size={17} />
            </button>
          ) : null}
        </div>
        {children}
      </div>
    </div>
  );
}
